  "STATEMENTS": {
    "me": "是我闩的门。",
    "V1_0": "苏泠当时在她房里。",
    "V1_1": "苏泠当时在活动厅。",
    "V1_2": "苏泠当时在备餐间。",
    "V2_0": "霍铎当时守在铜口旁。",
    "V2_1": "霍铎当时在他房里。",
    "V2_2": "霍铎当时在门厅。",
    "V3_0": "门外没有人。那声音是从主楼对着铜口说的，从管接头漏到了门边。",
    "V3_1": "门外确实有人在喊。",
    "V4_0": "他说的是：闩门，别开。",
    "V4_1": "他说的是：开门，救我。",
    "V5_0": "我信霍铎。",
    "V5_1": "我更信苏泠。",
    "V5_2": "我谁都不全信，自己去看了。",
    "trust": "我信霍铎——我们早已相熟。",
    "V6_0": "我们原本素不相识。",
    "V6_1": "我们早已相熟。"
  },
  "WHISPERS": {
    "huo": "图纸就在主楼。记得它的人，是你。",
    "su": "那墙里的声音，你昨夜已经听过一次。还有你从未听过的，就在后面。",
    "shen": "这罐子记得你护过的每一个人。你想护住的，都在里面。"
  },
  "HELP_NOTES": {
    "E4": "沈鼎：“这布是我拧的，这手法我认得。”",
    "E5": "苏泠用音叉轻敲凹痕：音色与敲桌面不同。“这里贴着空管。”",
    "E6": "苏泠读谱：“男声，很低。前两个字太轻，我听不出。”",
    "E7": "霍铎辨认：“是我的字。⊥ 是闩，✕ 是禁止……◎ 我不确定。”放大镜图样，他认不出指谁。",
    "E9": "沈鼎：“我泡茶按人放糖。”——“可我怎么会知道谁不吃糖？”",
    "E10": "沈鼎：“是我喂的。……这罐子，不是这一两天才养的。”",
    "E11": "在痕迹旁逐人比对过手掌轮廓：半枚手印，比四个人的手掌都窄。"
  },
